QCheckBox* diagonal(QDialog& popup,const char* direction){auto* result=popup.findChild<QCheckBox*>(QString("formatCells.border.")+direction);require(result&&result->isVisible()&&result->isEnabled(),"Both source diagonal icons are visible, enabled native border controls");return result;}
bool darkNear(const QImage& image,int x,int y){for(int dy=-1;dy<=1;++dy)for(int dx=-1;dx<=1;++dx){const auto color=image.pixelColor(x+dx,y+dy);if(color.red()<30&&color.green()<30&&color.blue()<30)return true;}return false;}
bool redNear(const QImage& image,int x,int y){for(int dy=-2;dy<=2;++dy)for(int dx=-2;dx<=2;++dx){const auto color=image.pixelColor(x+dx,y+dy);if(color.red()>180&&color.green()<80&&color.blue()<80)return true;}return false;}
