void sharedDiagonalInvariant(){
 const Json red={{"style","thin"},{"color","#ff0000"}};
 for(const Json bad:Json::array({Json{{"diagonalUp",red},{"diagonalDown",{{"style","medium"},{"color","#ff0000"}}}},Json{{"diagonalUp",red},{"diagonalDown",{{"style","thin"},{"color","#0000ff"}}}}})){
  auto imported=WorkbookSession().snapshot();const auto sheet=imported["sheets"][0]["id"];imported["sheets"][0]["cells"]=Json::array({{{"row",1},{"col",1},{"input","42"},{"style",{{"border",bad}}}}});bool rejected=false;try{WorkbookSession invalid(imported);}catch(const std::exception&){rejected=true;}require(rejected,"Imported diagonals with different shared line/color must be rejected before native persistence can discard one direction's styling");
  WorkbookSession session;const auto before=session.snapshot();std::string error;require(!session.apply(0,Json::array({{{"type","set_cell"},{"sheet",sheet},{"row",1},{"col",1},{"input","changed"}},{{"type","set_style"},{"sheet",sheet},{"row",1},{"col",1},{"style",{{"border",bad}}}}}),&error)&&session.snapshot()==before&&!session.canUndo(),"Inconsistent diagonal cell operations reject atomically with no undo entry");
  require(!session.apply(0,Json::array({{{"type","set_sheet_layout"},{"sheet",sheet},{"defaultStyle",{{"border",bad}}}}}),&error)&&session.snapshot()==before,"Inconsistent default diagonal style rejects atomically");
  rejected=false;try{validatedWorksheetCellStyle({{"border",bad}});}catch(const std::exception&){rejected=true;}require(rejected,"The public formatting validator rejects incompatible active diagonals before batching cells");
 }
 auto valid=WorkbookSession().snapshot();valid["sheets"][0]["cells"]=Json::array({{{"row",1},{"col",1},{"input","42"},{"style",{{"border",{{"diagonalUp",{{"style","thin"},{"color","#AABBCC"}}},{"diagonalDown",{{"style","thin"},{"color","#aabbcc"}}}}}}}}});WorkbookSession equivalent(valid);require(equivalent.snapshot().at("sheets").at(0).at("cells").size()==1,"Equivalent RGB casing does not make a shared diagonal style inconsistent");
 Fixture f;require(f.model->apply(Json::array({{{"type","set_cell"},{"sheet",f.model->sheetId().toStdString()},{"row",2},{"col",2},{"input","42"},{"style",{{"border",{{"diagonalUp",{{"style","medium"},{"color","#ff0000"}}}}}}}}})),"Seed an existing native upward diagonal");f.select();
 f.dialog([&](QDialog& popup){require(diagonal(popup,"diagonalUp")->isChecked(),"Reopening keeps the existing diagonal direction active");QTest::mouseClick(diagonal(popup,"diagonalDown"),Qt::LeftButton);QTest::keyClick(&popup,Qt::Key_Return);});
 const auto border=f.model->cellStyle(1,1).at("border");require(border.at("diagonalUp")==border.at("diagonalDown"),"Enabling the other diagonal synchronizes both active directions to one native line/color");
}
