const Json& storedCell(const Json& book,int column){for(const auto& cell:book.at("sheets").at(0).at("cells"))if(cell.at("row")==1&&cell.at("col")==column)return cell;throw std::runtime_error("Expected persisted border cell is missing");}
void assertRoundtrip(const Json& before,const Json& after){for(int column=1;column<=5;++column){const auto& a=storedCell(before,column);const auto& b=storedCell(after,column);require(a.at("input")==b.at("input"),"Native diagonal persistence preserves populated and formatted-blank inputs");const auto border=b.at("style").value("border",Json::object());require(border.size()==a.at("style").at("border").size(),"Native diagonal persistence retains precisely its active directions and independent edges");for(const auto& [name,edge]:a.at("style").at("border").items())require(border.at(name).at("style")==edge.at("style")&&QColor(QString::fromStdString(border.at(name).at("color")))==QColor(QString::fromStdString(edge.at("color"))),"Native diagonal persistence retains the shared line style and RGB color");}require(storedCell(after,4).at("style").at("bold")==true&&QColor(QString::fromStdString(storedCell(after,4).at("style").at("fill")))==QColor("#ffff00"),"Diagonal flags do not overwrite independent font or fill bits");}
pugi::xml_node xmlBorder(pugi::xml_document& doc,const WorkbookPackage& package,int column){const auto id=storedCell(package.workbook,column).at("style").at("ooxmlStyleId").get<unsigned>();auto xf=doc.document_element().child("cellXfs").first_child();for(unsigned i=0;i<id;++i)xf=xf.next_sibling();auto border=doc.document_element().child("borders").first_child();for(unsigned i=0;i<xf.attribute("borderId").as_uint();++i)border=border.next_sibling();return border;}
void xlsxPersistence(){
 QTemporaryDir files;const auto path=files.filePath("diagonals.xlsx").toStdString();const auto book=persistenceFixture();writeWorkbook(path,book);auto package=readWorkbook(path);assertRoundtrip(book,package.workbook);
 pugi::xml_document doc;require(doc.load_string(package.entries.at("xl/styles.xml").c_str()),"Read actual native OOXML style records");for(const auto [column,up,down]:{std::tuple{1,true,true},std::tuple{2,true,false},std::tuple{3,false,true},std::tuple{4,false,false},std::tuple{5,true,true}}){const auto border=xmlBorder(doc,package,column);require(border.attribute("diagonalUp").as_bool()==up&&border.attribute("diagonalDown").as_bool()==down,"Native OOXML direction flags match each independent source direction");if(up||down)require(border.child("diagonal").attribute("style")&&!border.child("diagonal").next_sibling("diagonal"),"Both native directions share exactly one diagonal style/color element");}
 auto clear=package.workbook;for(auto& cell:clear["sheets"][0]["cells"])if(cell.at("row")==1&&cell.at("col")==1)cell["style"]["border"]=Json::object();writeWorkbook(path,clear,&package);package=readWorkbook(path);require(storedCell(package.workbook,1).at("style").value("border",Json::object()).empty(),"Removing diagonals clears their native flags and inherited line style on save/reopen");doc.reset();require(doc.load_string(package.entries.at("xl/styles.xml").c_str()),"Re-read edited native styles");const auto cleared=xmlBorder(doc,package,1);require(!cleared.attribute("diagonalUp").as_bool()&&!cleared.attribute("diagonalDown").as_bool()&&!cleared.child("diagonal").attribute("style"),"Edited OOXML cannot retain stale copied diagonal flags/style");
}
void inspectBiffDiagonals(const std::string& path,bool cleared){
 std::ifstream input(path,std::ios::binary);const std::string file{std::istreambuf_iterator<char>(input),{}};xls::xls_error_t error=xls::LIBXLS_OK;std::unique_ptr<xls::xlsWorkBook,decltype(&xls::xls_close_WB)> native(xls::xls_open_buffer(reinterpret_cast<const unsigned char*>(file.data()),file.size(),"UTF-8",&error),xls::xls_close_WB);require(native!=nullptr,"An independent CFB/BIFF parser opens the genuine legacy file");std::unique_ptr<xls::xlsWorkSheet,decltype(&xls::xls_close_WS)> sheet(xls::xls_getWorkSheet(native.get(),0),xls::xls_close_WS);require(sheet&&xls::xls_parseWorkSheet(sheet.get())==xls::LIBXLS_OK,"Parse real legacy worksheet records");
 for(const auto [column,flags,kind]:{std::tuple{0,cleared?0U:3U,cleared?0U:2U},std::tuple{1,2U,1U},std::tuple{2,1U,6U},std::tuple{3,0U,0U},std::tuple{4,3U,7U}}){const auto* cell=xls::xls_cell(sheet.get(),0,column);require(cell&&cell->xf<native->xfs.count,"Legacy cell refers to a real XF style");const auto& xf=native->xfs.xf[cell->xf];require(((xf.linestyle>>30U)&3U)==flags&&((xf.linecolor>>21U)&15U)==kind,"Native CellXF uses specified grbitDiag bits30/31 and one dgDiag field at21..24");if(flags)require(((xf.linecolor>>14U)&127U)!=0,"Native active diagonal has its specified shared palette color at14..20");if(column==3)require(((xf.linecolor>>26U)&63U)==1&&((xf.linestyle>>8U)&15U)==1,"Shared diagonal fields do not overlap native fill or top border fields");}
}
void biffPersistence(){
 QTemporaryDir files;const auto path=files.filePath("diagonals.xls").toStdString();const auto book=persistenceFixture();writeBiffWorkbook(path,book);auto package=readWorkbook(path);assertRoundtrip(book,package.workbook);inspectBiffDiagonals(path,false);auto clear=package.workbook;for(auto& cell:clear["sheets"][0]["cells"])if(cell.at("row")==1&&cell.at("col")==1)cell["style"]["border"]=Json::object();writeBiffWorkbook(path,clear,&package);package=readWorkbook(path);require(storedCell(package.workbook,1).at("style").at("border").empty(),"Legacy save/reopen clears removed diagonals");inspectBiffDiagonals(path,true);
}
