int main(int argc,char** argv){QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{const std::string mode=argc>1?argv[1]:"all";if(mode=="all"||mode=="ui")nativeEditing();if(mode=="all"||mode=="validation")sharedDiagonalInvariant();if(mode=="all"||mode=="paint")actualCellPainting();if(mode=="all"||mode=="reopen")reopenDiagonal();if(mode=="all"||mode=="preview")previewDiagonalClick();if(mode=="all"||mode=="xlsx")xlsxPersistence();if(mode=="all"||mode=="biff")biffPersistence();std::cout<<"Native diagonal border "<<mode<<" passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
